async page => await page.evaluate(async()=>{const rows=[];const sample=()=>{const a=document.getElementById('actor-player'),s=a.querySelector('.actor-sprite'),r=a.getBoundingClientRect();rows.push({pose:a.dataset.pose,phase:a.dataset.phase,x:r.x,image:getComputedStyle(s).backgroundImage});};let running=true;const tick=()=>{sample();if(running)requestAnimationFrame(tick);};tick();await CombatActors.attack('player');running=false;sample();return {reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,poses:[...new Set(rows.map(r=>r.pose))],images:[...new Set(rows.map(r=>r.image))],travel:Math.max(...rows.map(r=>r.x))-Math.min(...rows.map(r=>r.x)),samples:rows.length};})
